import { useTRPC } from "@/lib/trpc";
import { useQuery } from "@tanstack/react-query";

export const Route = createFileRoute("/_authenticated/leagues/")({
	component: LeaguesListPage,
});

function LeaguesListPage() {
	const trpc = useTRPC();
	const { data: leaguesData, isPending } = useQuery(trpc.league.list.queryOptions());
	const organizations = leaguesData?.leagues;
	const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
	const [editingOrg, setEditingOrg] = useState<{
		id: string;
		name: string;
		slug: string;
		logo?: string | null;
		role: string;
	} | null>(null);

	return (
		<div className="flex min-h-screen flex-col">
			<Header
				includeLogoutButton
				includeSidebarTrigger={false}
				rightContent={
					<GlowButton
						icon={Add01Icon}
						glowColor={glowColors.blue}
						size="sm"
						className="gap-1.5"
						onClick={() => setIsCreateDialogOpen(true)}
					>
						League
					</GlowButton>
				}
			/>
			<main className="flex-1 p-4">
				<div className="mx-auto max-w-4xl">
					{isPending ? (
						<div className="flex h-64 items-center justify-center text-sm text-muted-foreground">
							Loading leagues...
						</div>
					) : !organizations || organizations.length === 0 ? (
						<div className="flex h-64 flex-col items-center justify-center gap-3 text-sm text-muted-foreground">
							<div className="flex h-12 w-12 items-center justify-center rounded-full bg-background shadow-sm">
								<span className="text-lg">🏆</span>
							</div>
							<p>No leagues found</p>
							<GlowButton
								icon={Add01Icon}
								glowColor={glowColors.blue}
								variant="outline"
								className="gap-1.5"
								onClick={() => setIsCreateDialogOpen(true)}
							>
								Create First League
							</GlowButton>
						</div>
					) : (
						<div className="grid grid-cols-1 md:grid-cols-2 gap-4">
							{organizations.map((org) => {
								const canEdit = org.role === "owner" || org.role === "editor";
								return (
									<div key={org.id} className="border">
										<Link to="/leagues/$slug" params={{ slug: org.slug }} className="block">
											<RowCard
												icon={
													<AvatarWithFallback
														src={org.logo}
														name={org.name}
														alt={org.name}
														size="lg"
													/>
												}
												title={org.name}
												subtitle={<span>/{org.slug}</span>}
											>
												{canEdit && (
													<Button
														variant="ghost"
														size="sm"
														onClick={(e) => {
															e.preventDefault();
															e.stopPropagation();
															setEditingOrg(org);
														}}
													>
														<span className="hidden sm:inline">Edit League</span>
														<span className="sm:hidden">
															<HugeiconsIcon icon={PencilEdit01Icon} className="size-4" />
														</span>
													</Button>
												)}
											</RowCard>
										</Link>
									</div>
								);
							})}
						</div>
					)}
				</div>
			</main>
			<CreateLeagueDialog
				isOpen={isCreateDialogOpen}
				onClose={() => setIsCreateDialogOpen(false)}
			/>
			{editingOrg && (
				<EditLeagueDialog
					isOpen={!!editingOrg}
					onClose={() => setEditingOrg(null)}
					league={editingOrg}
				/>
			)}
		</div>
	);
}

